/**
 * Core Book - Provides book action data via render props
 * NO AsChildSlot, NO asChild - that belongs in high-level component
 */
import { useState } from 'react';
import { useService } from '@wix/services-manager-react';
import { BookingServiceDefinition } from '../../../services/booking/booking.js';
import { canBook } from '../../../services/booking/book-action/canBook.js';
import { BookResultType, } from '../../../services/booking/book-action/types.js';
/**
 * Core Book component - provides book action data via render props.
 * Used internally by higher-level Booking.Actions.Book component.
 *
 * The onCheckout callback receives the checkoutId for internal use.
 * The high-level component wraps this to provide a simpler API with
 * navigateToCheckout() that has the checkoutId already captured.
 *
 * @example
 * ```tsx
 * <Book
 *   onCheckout={({ checkoutId }) => {
 *     // Use checkoutId to navigate to checkout
 *     navigateToCheckout(checkoutId);
 *   }}
 *   onComplete={({ orderId }) => {
 *     // Use orderId to navigate to thank you page
 *     navigate(`/thank-you?orderId=${orderId}`);
 *   }}
 * >
 *   {({ isLoading, error, canBook, onClick, disabled }) => (
 *     <button onClick={onClick} disabled={disabled}>
 *       {isLoading ? 'Booking...' : 'Book Now'}
 *     </button>
 *   )}
 * </Book>
 * ```
 */
export function Book(props) {
    const { children, onCheckout, onComplete, onError, disabled } = props;
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const bookingService = useService(BookingServiceDefinition);
    const serviceSelections = bookingService.serviceSelections.get();
    const formSubmission = bookingService.formSubmission.get();
    const canBookValue = canBook({ serviceSelections, formSubmission });
    const handleClick = async () => {
        setIsLoading(true);
        setError(null);
        try {
            const result = await bookingService.actions.book();
            if (result.type === BookResultType.CheckoutRequired) {
                await onCheckout?.({ cartId: result.cartId });
            }
            else {
                await onComplete?.({ orderId: result.orderId });
            }
            setIsLoading(false);
        }
        catch (e) {
            const bookingError = {
                message: e instanceof Error ? e.message : 'Booking failed',
                errorObject: e,
            };
            setError(bookingError);
            onError?.(bookingError);
            setIsLoading(false);
        }
    };
    const isDisabled = isLoading || disabled || !canBookValue;
    return children({
        isLoading,
        error,
        canBook: canBookValue,
        onClick: handleClick,
        disabled: isDisabled,
    });
}
